import {samples} from './samples.js';
let active=-1,option=0,tested=false;
const app=document.querySelector('#app');
const titleCase=s=>s[0].toUpperCase()+s.slice(1);
function membership(){return `<section class="panel demo-membership"><div><p class="eyebrow">Turn the sample into your own work</p><h2>Build your portfolio with Specly.</h2><p>Create a verified account and start your 3-day trial to choose from 45 member projects—15 at each difficulty—save your work, and export portfolio reports.</p><small>Payment method required. Then US$15/month plus applicable tax until canceled. Cancel before the trial ends to avoid the first charge.</small></div><a class="button primary" href="./commerce.html">View membership →</a></section>`}
function catalog(){return `<section class="intro"><div><div class="eyebrow">Engineering projects for internships & jobs</div><h1>Build engineering projects.<br><em>Put them on your portfolio.</em></h1><p>Get a focused brief, work through design decisions, and turn your tests into evidence you can discuss in an interview.</p></div></section><div class="sectionbar"><strong>Try a small sample</strong><span class="count">3 projects · one at each difficulty</span></div><p class="levelnote">Explore a brief and compare three preset choices. Full design controls, saved work, and portfolio exports are included with a trial or membership.</p><div class="cards">${samples.map((s,i)=>`<article class="missioncard" style="--accent:${s.color}"><div class="cardtop"><span>${titleCase(s.level)}</span><span>Sample 0${i+1}</span></div><div class="sample-label">${['Structures','Vibration','Thermal'][i]}</div><div class="cardbody"><h3>${s.title}</h3><p>${s.description}</p></div><div class="cardfoot"><span>Guided preview</span><button class="circlebutton" data-sample="${i}">Try sample →</button></div></article>`).join('')}</div>${membership()}`}
function workspace(){const s=samples[active],r=s.options[option];return `<div class="workspacehead"><div><p class="eyebrow">${s.level} · limited sample</p><h1>${s.title}</h1><p>${s.description}</p></div><button class="button ghost" data-back>All three samples</button></div><div class="workgrid"><section class="panel"><p class="eyebrow">The brief</p><h2>Explore one design decision.</h2><p>${s.context}</p><label class="sample-field" for="sample-choice">${s.label}</label><select id="sample-choice">${s.options.map((o,i)=>`<option value="${i}" ${i===option?'selected':''}>${o.value} ${s.unit}${i===0?' · baseline':''}</option>`).join('')}</select><p class="note">Sample controls are limited to three preset configurations. Other parameters stay fixed.</p><button class="button primary" data-test>Test this choice →</button></section><section class="panel"><p class="eyebrow">${tested?'Sample results':'Predict before you test'}</p><h2>${tested?(r.pass?'Modeled requirements met.':'Room to improve.'):'What do you expect to change?'}</h2>${tested?`<div class="checks">${r.checks.map(c=>`<div class="req"><span>${c.label}</span><strong>${Number(c.value.toFixed(3))} ${c.unit} · ${c.pass?'Pass':'Revise'}</strong></div>`).join('')}</div><p>${r.advice}</p>`:'<p>Try one configuration and compare its calculated results with the brief. The full studio lets you control the design, keep an iteration history, and explain your tradeoffs.</p>'}<p class="note">This preview keeps no saved projects or test history. Leaving or refreshing resets your work.</p></section></div><details class="panel"><summary>Model assumptions and limitations</summary><p>${s.assumptions}</p></details><div class="sample-locked"><div><strong>Want to save this work or make a portfolio report?</strong><p>A verified account and active 3-day trial or membership are required.</p></div><a class="button" href="./commerce.html">Unlock saving & exports →</a></div>${membership()}`}
function render(){app.innerHTML=`<header class="topbar"><button class="brand" data-back>specly<small>Engineering for your portfolio</small></button><div class="topright"><span class="storage">Sample only · not saved</span><a class="button small" href="./commerce.html">Account & membership</a></div></header><main id="main" class="sample-main">${active<0?catalog():workspace()}<footer><span>Specly · Your work. Your decisions.</span><span>Educational analytical models</span></footer></main>`}
document.addEventListener('click',e=>{const sample=e.target.closest('[data-sample]');if(sample){active=Number(sample.dataset.sample);option=0;tested=false;render();window.scrollTo(0,0)}if(e.target.closest('[data-back]')){active=-1;option=0;tested=false;render();window.scrollTo(0,0)}if(e.target.closest('[data-test]')){tested=true;render()}});
document.addEventListener('change',e=>{if(e.target.id==='sample-choice'){option=Number(e.target.value);tested=false;render()}});
render();
